import{_ as r,o as a,c as d,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"سمبیوسس لیبر قانون","description":"","frontmatter":{},"headers":[],"relativePath":"ur/41-共生劳动法.md","filePath":"ur/41-共生劳动法.md"}'),o={name:"ur/41-共生劳动法.md"};function e(i,t,n,s,h,u){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="سمبیوسس-لیبر-قانون" tabindex="-1">سمبیوسس لیبر قانون <a class="header-anchor" href="#سمبیوسس-لیبر-قانون" aria-label="Permalink to &quot;سمبیوسس لیبر قانون&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>41</td></tr><tr><td>ماڈیول</td><td>قانونی نظام اور گورننس کا فریم ورک</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>سمبیوسس محنت، زیادہ محنت زیادہ فائدہ، محنت کے حقوق، مشترکہ پیداوار معاہدہ، استحصال مخالف</td></tr></tbody></table><h2 id="أولاً-قانون-سازی-کا-مقصد-اور-بنیادی-اصول" tabindex="-1">أولاً. قانون سازی کا مقصد اور بنیادی اصول <a class="header-anchor" href="#أولاً-قانون-سازی-کا-مقصد-اور-بنیادی-اصول" aria-label="Permalink to &quot;أولاً. قانون سازی کا مقصد اور بنیادی اصول&quot;">​</a></h2><p>《سمبیوسس لیبر قانون》 اینکر سمبیوسس تہذیب کے قانونی نظام میں 《سمبیوسس آئین》 کے متوازی بنیادی قوانین میں سے ایک ہے، اور اس کا مقصد ہینگیوانژو کے اندر تمام محنت اور شراکت کی سرگرمیوں کو منظم کرنا، &quot;زیادہ محنت زیادہ فائدہ، خود بخود بڑھنا&quot; کی تقسیم کا نظام قائم کرنا، اور قانونی سطح سے لوٹ مار کے استحصال کی جڑیں اکھاڑ پھینکنا ہے۔</p><p>یہ قانون درج ذیل بنیادی اصول قائم کرتا ہے:</p><table tabindex="0"><thead><tr><th>اصول</th><th>مواد</th></tr></thead><tbody><tr><td>محنت کی وقار کا اصول</td><td>تمام قانونی محنت قانون سے محفوظ ہے، مزدور کی ذاتی وقار کی خلاف ورزی نہیں کی جا سکتی</td></tr><tr><td>زیادہ محنت زیادہ فائدہ کا اصول</td><td>محنت کی اجرت شراکت کی مقدار سے براہ راست جڑی ہوئی ہے، جتنی زیادہ شراکت اتنا زیادہ فائدہ، بغیر محنت فائدہ ممنوع ہے</td></tr><tr><td>رضاکارانہ محنت کا اصول</td><td>جبری محنت اور غلامی ممنوع ہے، مزدور کو محنت کے مواد اور طریقے کو آزادانہ طور پر منتخب کرنے کا حق ہے</td></tr><tr><td>منصفانہ اجرت کا اصول</td><td>یکساں کام پر یکساں اجرت، نسل، سادھنہ کی سطح، اصل کی بنیاد پر اجرت میں امتیازی سلوک ممنوع ہے</td></tr><tr><td>محنت کی ضمانت کا اصول</td><td>ریاست اور تہذیب پر مزدوروں کے لیے محفوظ ماحول کام اور بنیادی سماجی تحفظ فراہم کرنے کی ذمہ داری ہے</td></tr><tr><td>سمبیوسس تعاون کا اصول</td><td>مزدوروں کے درمیان تعاون اور باہمی مدد کی حوصلہ افزائی، شدید مسابقت اور زیرو سم کھیل کی مخالفت</td></tr></tbody></table><h2 id="ثانياً-مزدوروں-کے-بنیادی-حقوق" tabindex="-1">ثانياً. مزدوروں کے بنیادی حقوق <a class="header-anchor" href="#ثانياً-مزدوروں-کے-بنیادی-حقوق" aria-label="Permalink to &quot;ثانياً. مزدوروں کے بنیادی حقوق&quot;">​</a></h2><p>سمبیوسس لیبر قانون ہینگیوانژو کے اندر تمام محنت کی صلاحیت والی زندگی کو درج ذیل حقوق عطا کرتا ہے:</p><ol><li><strong>مساوی ملازمت کا حق</strong>: کوئی بھی زندگی ملازمت کی تلاش اور ملازمت کے عمل میں نسل، سادھنہ کی سطح، اصل، جنس وغیرہ کی وجہ سے امتیازی سلوک کا شکار نہیں ہوتی۔</li><li><strong>آزادانہ پیشے کا انتخاب کا حق</strong>: مزدور کو اپنی مرضی اور صلاحیت کے مطابق پیشہ، عہدہ اور کام کی جگہ منتخب کرنے کا حق ہے، اور قانون کے مطابق پیشہ تبدیل کرنے کا حق ہے۔</li><li><strong>منصفانہ اجرت کا حق</strong>: مزدور کو اپنی محنت کی شراکت کے مطابق اجرت حاصل کرنے کا حق ہے، اجرت تہذیب کے مقرر کردہ کم از کم ضمانت کے معیار سے کم نہیں ہو سکتی۔</li><li><strong>آرام اور چھٹیوں کا حق</strong>: مزدور کو مناسب کام کے وقت کی ترتیب اور باقاعدہ چھٹیوں کا حق ہے، کام کے وقت کو بے حد بڑھانا ممنوع ہے۔</li><li><strong>محنت کی حفاظت کا حق</strong>: مزدور کو محفوظ، صحت مند ماحول میں کام کرنے کا حق ہے، آجر کو معیار کے مطابق کام کے تحفظ کے حالات فراہم کرنے چاہئیں۔</li><li><strong>پیشہ ورانہ تربیت کا حق</strong>: مزدور کو پیشہ ورانہ مہارت کی تربیت اور سادھنہ کی رہنمائی حاصل کرنے کا حق ہے، آجر اور ریاست پر تربیت کے وسائل فراہم کرنے کی ذمہ داری ہے۔</li><li><strong>جمعیت بنانے اور مذاکرات کا حق</strong>: مزدور کو قانون کے مطابق مزدوروں کی جمعیت بنانے یا اس میں شامل ہونے کا حق ہے، اور اجتماعی مذاکرات کے ذریعے اپنے حقوق کی حفاظت کرنے کا حق ہے۔</li><li><strong>شکایت اور ریلیف کا حق</strong>: مزدور جب اس کے محنت کے حقوق کی خلاف ورزی ہوتی ہے تو اس کے پاس لیبر آربیٹریشن ادارے اور سمبیوسس عدالت میں شکایت اور مقدمہ دائر کرنے کا حق ہے۔</li></ol><h2 id="ثالثاً-مشترکہ-پیداوار-معاہدے-کے-طریقہ-کار-کی-قانونی-شکل" tabindex="-1">ثالثاً. مشترکہ پیداوار معاہدے کے طریقہ کار کی قانونی شکل <a class="header-anchor" href="#ثالثاً-مشترکہ-پیداوار-معاہدے-کے-طریقہ-کار-کی-قانونی-شکل" aria-label="Permalink to &quot;ثالثاً. مشترکہ پیداوار معاہدے کے طریقہ کار کی قانونی شکل&quot;">​</a></h2><p>مشترکہ پیداوار معاہدے کا طریقہ کار اینکر سمبیوسس تہذیب کے وسائل کی تقسیم کا بنیادی نظام ہے، اور 《سمبیوسس لیبر قانون》 اسے قانونی شکل میں مقرر کرتا ہے:</p><ul><li><strong>معاہدے کا موضوع</strong>: کوئی بھی محنت کی صلاحیت والی زندگی معاہدے کا موضوع بن سکتی ہے، فرد یا اجتماعی دونوں معاہدہ کر سکتے ہیں۔</li><li><strong>معاہدے کا مواد</strong>: سادھنہ وسائل کی ترقی، سطح کی دیکھ بھال، علم کی وراثت، ٹیکنالوجی کی تحقیق اور ترقی، عوامی خدمات وغیرہ کے شعبوں میں شامل ہے لیکن محدود نہیں۔</li><li><strong>معاہدے کی مدت</strong>: معاہدے کے مواد کی نوعیت کے مطابق طے کی جاتی ہے، قلیل مدتی معاہدہ ایک سے تین سال، طویل مدتی معاہدہ پانچ سے بیس سال، میعاد ختم ہونے پر تجدید کیا جا سکتا ہے۔</li><li><strong>منافع کی تقسیم</strong>: معاہدہ کار کا منافع اس کی پیداوار سے براہ راست جڑا ہوا ہے، پیداوار کا ایک حصہ عوامی جمع کو دیا جاتا ہے، باقی حصہ معاہدہ کار کی ملکیت ہے۔</li><li><strong>اخراج کا طریقہ کار</strong>: معاہدہ کار کو مناسب مدت میں مقدماتی اطلاع کے بعد معاہدے سے نکلنے کا حق ہے، اور اسے معاہدے کے تعلق میں جبری طور پر باندھا نہیں جا سکتا۔</li><li><strong>تنازعات کا حل</strong>: معاہدے کے تنازعات کو ترجیحی طور پر لیبر آربیٹریشن کے ذریعے حل کیا جاتا ہے، آربیٹریشن کے نتیجے سے عدم اطمینان پر سمبیوسس عدالت میں مقدمہ دائر کیا جا سکتا ہے۔</li></ul><h2 id="رابعاً-خصوصی-محنت-کی-حفاظت" tabindex="-1">رابعاً. خصوصی محنت کی حفاظت <a class="header-anchor" href="#رابعاً-خصوصی-محنت-کی-حفاظت" aria-label="Permalink to &quot;رابعاً. خصوصی محنت کی حفاظت&quot;">​</a></h2><p>ہینگیوانژو کے اندر مختلف زندگی کی شکلوں کی خصوصی ضروریات کو مدنظر رکھتے ہوئے، یہ قانون خصوصی محنت کی حفاظت کا نظام قائم کرتا ہے:</p><table tabindex="0"><thead><tr><th>تحفظ کا مقصد</th><th>خصوصی تحفظ کے اقدامات</th></tr></thead><tbody><tr><td>ابتدائی سادھک</td><td>ان کی صلاحیت سے باہر خطرناک کام تفویض نہیں کیے جا سکتے، اور اساتذہ کی رہنمائی فراہم کی جانی چاہیے</td></tr><tr><td>حمل اور زچگی کے دور میں خاتون زندگی</td><td>کم از کم چھ ماہ کی تنخواہ دار زچگی کی چھٹی کا حق ہے، دودھ پلانے کے دور میں شدید کام تفویض نہیں کیے جا سکتے</td></tr><tr><td>معذور اور زخمی/بیمار زندگی</td><td>مناسب کام کی جگہ کی ایڈجسٹمنٹ اور بلا رکاوٹ کام کے ماحول کی ضمانت کا حق ہے</td></tr><tr><td>دوسری نسلوں کے مزدور</td><td>آجر کو دوسری نسلوں کی جسمانی خصوصیات اور ثقافتی عادات کا احترام کرنا چاہیے، اور موافق کام کے حالات فراہم کرنے چاہئیں</td></tr><tr><td>بوڑھے مزدور</td><td>ایک مخصوص عمر تک پہنچنے کے بعد کام کی شدت کم کرنے یا مشاورتی عہدے پر منتقل ہونے کے لیے درخواست دے سکتے ہیں</td></tr></tbody></table><h2 id="خامساً-قانونی-ذمہ-داری-اور-نفاذ-کی-ضمانت" tabindex="-1">خامساً. قانونی ذمہ داری اور نفاذ کی ضمانت <a class="header-anchor" href="#خامساً-قانونی-ذمہ-داری-اور-نفاذ-کی-ضمانت" aria-label="Permalink to &quot;خامساً. قانونی ذمہ داری اور نفاذ کی ضمانت&quot;">​</a></h2><p>آجر جو اس قانون کی دفعات کی خلاف ورزی کرتا ہے، جرم کی شدت کے مطابق درج ذیل ذمہ داری اٹھائے گا:</p><ol><li>مزدور کو واجب الادا اجرت اور معاوضہ ادا کرنا (معاوضہ بقایا اجرت کا ایک سے تین گنا ہے)۔</li><li>مقررہ مدت میں اصلاح کرنے کا حکم دیا جائے گا، مدت میں اصلاح نہ کرنے پر جرمانہ کیا جائے گا۔</li><li>سنگین جرم کی صورت میں، کاروبار کا لائسنس منسوخ کر دیا جائے گا اور متعلقہ ذمہ دار افراد کو ایک مخصوص مدت کے لیے انتظامی کام میں مشغول ہونے سے منع کیا جائے گا۔</li><li>اگر جرم قائم ہوتا ہے تو قانون کے مطابق مجرمانہ ذمہ داری عائد کی جائے گی۔</li></ol><p>ریاست لیبر انسپکشن ادارہ قائم کرتی ہے، جو آجروں کی طرف سے لیبر قانون کی تعمیل کی نگرانی اور معائنہ کے لیے ذمہ دار ہے۔ مزدوروں کی جمعیت مزدوروں کی نمائندگی میں لیبر انسپکشن اور اجتماعی مذاکرات میں حصہ لینے کا حق رکھتی ہے۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>《سمبیوسس لیبر قانون》 اینکر سمبیوسس تہذیب کے &quot;زیادہ محنت زیادہ فائدہ&quot; کے تصور کا قانونی ذریعہ ہے۔ اس نے محنت کو استحصال کے مقصد سے ایک قابل احترام حق میں تبدیل کر دیا ہے، اور تقسیم کو لوٹ مار کے قبضے سے شراکت پر مبنی معاوضے میں تبدیل کر دیا ہے، اور تمام نسلوں کی مشترکہ ترقی کے لیے مضبوط محنت کے نظام کی بنیاد رکھی ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>40-共生宪法总纲 (سمبیوسس آئین کے بنیادی اصول)</li><li>06-多劳多得分配原理 (زیادہ محنت زیادہ فائدہ کی تقسیم کا اصول)</li><li>22-资源分配联产承包机制 (وسائل کی تقسیم کا مشترکہ پیداوار معاہدے کا طریقہ کار)</li><li>42-消费者保护法 (صارفین کے تحفظ کا قانون)</li></ul>',23)])])}const g=r(o,[["render",e]]);export{c as __pageData,g as default};
